(()=>{ window.__log=[]; window.__qlog=[]; let last=performance.now(); const Q=__quality();
 let lv=Q.quality.level, sc=Q.dyn.scale;
 const f=(now)=>{ const p=__player.ch.holder.position; const ch=__player.ch; __log.push([now-last, p.x, p.z, __player.speed, ch.curName, ch.cur?ch.cur.timeScale:0, __camera.position.x, __camera.position.z]); last=now;
   if (Q.quality.level!==lv||Q.dyn.scale!==sc){ __qlog.push([Math.round(now), Q.quality.level, +Q.dyn.scale.toFixed(2)]); lv=Q.quality.level; sc=Q.dyn.scale; }
   requestAnimationFrame(f); }; requestAnimationFrame(f); return 1; })()

(()=>{ const L=__log.slice(5); const dts=L.map(r=>r[0]).sort((a,b)=>a-b); const pct=(q)=>dts[Math.floor(q*(dts.length-1))].toFixed(1);
 let jumps=0; for(let i=1;i<L.length;i++){ const d=Math.hypot(L[i][1]-L[i-1][1], L[i][2]-L[i-1][2]); const exp=L[i][3]*Math.min(L[i][0],50)/1000; if (L[i][3]>0.5 && (d>exp*1.8+0.02)) jumps++; }
 const anims={}; L.forEach(r=>anims[r[4]]=(anims[r[4]]||0)+1);
 return JSON.stringify({frames:L.length, dt50:pct(.5), dt90:pct(.9), dt99:pct(.99), dtMax:dts[dts.length-1].toFixed(0), over100:dts.filter(d=>d>100).length, over250:dts.filter(d=>d>250).length, posJumps:jumps, anims, q:__qlog}); })()

